const input = $input.first().json;
const body = input.body && typeof input.body === "object" ? input.body : input;
function fail(code, message) { return [{ json: { action: "error", error: { code: code, message: message } } }]; }
function clean(s) {
  let out = "";
  for (let i = 0; i < s.length; i++) { const k = s.charCodeAt(i); if (k >= 32 && k !== 127) out += s[i]; }
  return out;
}
function isLetter(c) { return (c >= "a" && c <= "z") || (c >= "A" && c <= "Z") || c.charCodeAt(0) > 127; }
function isDigit(c) { return c >= "0" && c <= "9"; }
const name = clean(typeof body.name === "string" ? body.name : "").trim();
const email = clean(typeof body.email === "string" ? body.email : "").trim().toLowerCase();
const sessionId = typeof body.sessionId === "string" ? body.sessionId.trim() : "";
const requestId = typeof body.requestId === "string" && body.requestId.length < 80 ? body.requestId : "req-" + Date.now();

if (body.consent !== true) return fail("invalid_input", "Please tick the consent box so we can contact you.");
if (name.length < 2 || name.length > 80 || !isLetter(name[0])) return fail("invalid_input", "Please enter your name.");
for (let i = 0; i < name.length; i++) {
  const c = name[i];
  if (!(isLetter(c) || c === " " || c === "-" || c === "'" || c === ".")) return fail("invalid_input", "Please use letters only in your name.");
}
function validEmail(e) {
  if (e.length < 5 || e.length > 120) return false;
  const at = e.indexOf("@");
  if (at < 1 || at !== e.lastIndexOf("@")) return false;
  const domain = e.slice(at + 1);
  const dot = domain.lastIndexOf(".");
  if (dot < 1 || dot > domain.length - 3) return false;
  for (let i = 0; i < e.length; i++) {
    const c = e[i];
    if (!(isLetter(c) || isDigit(c) || c === "." || c === "_" || c === "%" || c === "+" || c === "-" || c === "@")) return false;
  }
  return true;
}
if (!validEmail(email)) return fail("invalid_input", "Please enter a valid email address.");
if (sessionId.length < 8 || sessionId.length > 80) return fail("invalid_input", "Invalid session.");

const sd = $getWorkflowStaticData("global");
if (!sd.leadRl) sd.leadRl = {};
const now = Date.now();
const day = new Date(now).toISOString().slice(0, 10);
if (sd.leadDay !== day) { sd.leadDay = day; sd.leadCount = 0; }
sd.leadCount = (sd.leadCount || 0) + 1;
if (sd.leadCount > 300) return fail("rate_limited", "Too many requests today. Please try again tomorrow.");
const stamps = (sd.leadRl[sessionId] || []).filter(function (t) { return now - t < 3600000; });
if (stamps.length >= 3) { sd.leadRl[sessionId] = stamps; return fail("rate_limited", "You have already submitted your details. We will be in touch."); }
stamps.push(now);
sd.leadRl[sessionId] = stamps;
const keys = Object.keys(sd.leadRl);
if (keys.length > 500) { keys.forEach(function (k) { const a = sd.leadRl[k]; if (!a.length || now - a[a.length - 1] > 3600000) delete sd.leadRl[k]; }); }

return [{ json: { action: "ok", lead: { name: name, email: email, sessionId: sessionId, requestId: requestId } } }];
